void ui_event_logo_background(lv_event_t * e)
{  
    lv_event_code_t event_code = lv_event_get_code(e);
    if(event_code == LV_EVENT_CLICKED) {
        static uint32_t last_click_tick = 0;
        static uint8_t  click_cnt = 0;
        uint32_t now = lv_tick_get();
        if(now - last_click_tick < 400){
            click_cnt++;
        }else{
            click_cnt = 1;
        }
        last_click_tick = now;

        if(click_cnt >= 2){
            click_cnt = 0;
            ui_nav_show_delete_old(UI_NAV_PAGE_OBD_PROTOCOL,
                                   LV_SCR_LOAD_ANIM_FADE_ON, 300, 0);
            ui_ScreenPageLogo = NULL;
            imageLogo = NULL;
        }  

        ESP_LOGD(TAG, "Logo LV_EVENT_CLICKED");
    }   
}

void ui_event_easter_egg_background(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_CLICKED && !ui_ext_showroom_is_active()) {
        ui_ext_showroom_handle_tap();
    }
}

// OTA mode is a modal radio workflow; the navigation manager owns its exit swipe.
void ui_event_easter_egg_ota_button(lv_event_t *e)
{
    LV_UNUSED(e);
    ui_nav_show(UI_NAV_PAGE_OTA_MODE, LV_SCR_LOAD_ANIM_FADE_ON, 300, 0, false);
}

// OTA mode screen: refresh status from the LVGL timer (called every 500ms)
void ui_ota_mode_refresh(void)
{
    if (ui_ScreenPageOTAMode == NULL) return;
    if (ui_LabelOTAModeStatus == NULL) return;

    if (ota_wifi_server_is_busy()) {
        lv_label_set_text(ui_LabelOTAModeStatus, "Receiving update...");
        lv_obj_set_style_text_color(ui_LabelOTAModeStatus, lv_color_hex(0x00CC66), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (ota_wifi_server_get_state() == OTA_WIFI_STATE_READY) {
        lv_label_set_text(ui_LabelOTAModeStatus, "WiFi ready — connect your phone");
        lv_obj_set_style_text_color(ui_LabelOTAModeStatus, lv_color_hex(0x00CC66), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (ota_wifi_server_get_state() == OTA_WIFI_STATE_IDLE) {
        lv_label_set_text(ui_LabelOTAModeStatus, "Starting WiFi...");
        lv_obj_set_style_text_color(ui_LabelOTAModeStatus, lv_color_hex(0xAAAAAA), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (ota_wifi_server_get_state() == OTA_WIFI_STATE_ERROR) {
        lv_label_set_text(ui_LabelOTAModeStatus, "WiFi error");
        lv_obj_set_style_text_color(ui_LabelOTAModeStatus, lv_color_hex(0xFF0000), LV_PART_MAIN | LV_STATE_DEFAULT);
    }
}

///////////////////// SCREENS ////////////////////

void ui_init(void)
{
    // OPTIMIZATION: Logo is already created and displayed by app_main.c before this function
    // to ensure both Master (with 2MB theme) and Slave show logo simultaneously.
    // Here we only load theme and create other UI elements.

    // Initialize theme partition system AFTER logo is visible
    // This loads the theme from theme_0/theme_1 partition, or falls back to default
    ESP_LOGI(TAG, "Initializing theme partition system");
    esp_err_t theme_ret = theme_engine_init();
    if (theme_ret == ESP_OK) {
        theme_info_t info;
        if (theme_get_info(&info) == ESP_OK) {
            ESP_LOGI(TAG, "Theme loaded: %s v%s by %s", info.name, info.version, info.author);
        }
        // Run test to print detailed theme info
        theme_engine_test();
    } else {
        ESP_LOGW(TAG, "Theme partition system initialization failed, using built-in themes");
    }

    // Load the saved UI theme BEFORE any screen is built, so every screen
    // picks up the active theme's colors at creation time.
    ui_theme_init();
    ui_helpers_init_edge_ring();

    // Keep page creation and route transitions in the central navigation registry.
    ui_nav_register_page(UI_NAV_PAGE_GEAR, &ui_ScreenPageGear, ui_ScreenPageGear_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_THEME_GAUGE, &ui_ScreenPageThemeGauge, ui_ScreenPageThemeGauge_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_RPM, &ui_ScreenPageRpm, ui_ScreenPageRpm_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_SPEED, &ui_ScreenPageSpeed, ui_ScreenPageSpeed_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_TEMP, &ui_ScreenPageTemp, ui_ScreenPageTemp_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_TPMS, &ui_ScreenPageTpms, ui_ScreenPageTpms_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_INFO, &ui_ScreenPageInfo, ui_ScreenPageInfo_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_NEEDLE, &ui_ScreenPageNeedle, ui_ScreenPageNeedle_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_CHART, &ui_ScreenPageOilPressure, ui_ScreenPageOilPressure_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_SKY_GAUGE, &ui_ScreenPageEasterEgg, ui_ScreenPageEasterEgg_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_BLE_SCAN, &ui_ScreenPageBLEScan, ui_ScreenPageBLEScan_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_SETTINGS, &ui_ScreenPageSettings, ui_ScreenPageSettings_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_ALERT_MEDIA, &ui_ScreenPageAlertMedia, ui_ScreenPageAlertMedia_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_MULTI_GAUGE, &ui_ScreenPageMultiGauge, ui_ScreenPageMultiGauge_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_TEMP_CONFIG, &ui_ScreenPageTempCustom, ui_ScreenPageTempCustom_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_TPMS_CONFIG, &ui_ScreenPageTpmsConfig, ui_ScreenPageTpmsConfig_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_INFO_CONFIG, &ui_ScreenPageInfoCustom, ui_ScreenPageInfoCustom_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_NEEDLE_CONFIG, &ui_ScreenPageNeedleConfig, ui_ScreenPageNeedleConfig_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_CHART_CONFIG, &ui_ScreenPageChartConfig, ui_ScreenPageChartConfig_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_CHART_ALARM, &ui_ScreenPageChartAlarm, ui_ScreenPageChartAlarm_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_OIL_WARN, &ui_ScreenPageOilWarn, ui_ScreenPageOilWarn_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_RPM_WARN, &ui_ScreenPageRpmWarn, ui_ScreenPageRpmWarn_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_SPEED_CONFIG, &ui_ScreenPageSpeedConfig, ui_ScreenPageSpeedConfig_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_OBD_PROTOCOL, &ui_ScreenPageODBProtocal, ui_ScreenPageODBProtocal_screen_init);
    ui_nav_register_page(UI_NAV_PAGE_OTA_MODE, &ui_ScreenPageOTAMode, ui_ScreenPageOTAMode_screen_init);
    ui_nav_register_leave_cb(UI_NAV_PAGE_BLE_SCAN, ui_nav_ble_leave);

    // MEMORY OPTIMIZATION: Conditionally create screens based on theme availability
    // If custom theme is loaded, skip built-in gauge pages (Gear/Rpm/Speed/Temp/Needle/OilPressure)
    // and rely on theme-provided pages instead. This saves ~40-60KB RAM for Master mode.
    bool has_custom_theme = false;
    theme_info_t theme_info;
    if (theme_get_info(&theme_info) == ESP_OK) {
        if (theme_info.id[0] != '\0' && strcmp(theme_info.id, "default") != 0) {
            has_custom_theme = true;
            ESP_LOGI(TAG, "Custom theme detected - skipping built-in gauge pages to save RAM");
        }
    }

    if (!has_custom_theme) {
        // No custom theme - create built-in gauge pages
        ui_ScreenPageGear_screen_init();
        ui_ScreenPageRpm_screen_init();
        ui_ScreenPageSpeed_screen_init();
        ui_ScreenPageTemp_screen_init();
        ui_ScreenPageOilPressure_screen_init();
        ui_ScreenPageNeedle_screen_init();
    } else {
        // Custom theme loaded - defer built-in gauge pages (only create if explicitly accessed)
        ui_ScreenPageGear = NULL;
        ui_ScreenPageRpm = NULL;
        ui_ScreenPageSpeed = NULL;
        ui_ScreenPageTemp = NULL;
        ui_ScreenPageOilPressure = NULL;
        ui_ScreenPageNeedle = NULL;
    }

    // System pages are always created (needed for settings/BLE/etc regardless of theme)
    ui_ScreenPageOilWarn_screen_init();
    ui_ScreenPageODBProtocal_screen_init();
    // The Info page is lazy-loaded on demand; its screen pointer must be initialized to NULL
    ui_ScreenPageInfo = NULL;
    ui_ScreenPageTempCustom = NULL;
    ui_ScreenPageTpms = NULL;
    ui_ScreenPageTpmsConfig = NULL;
    ui_ScreenPageInfoCustom = NULL;
    ui_ScreenPageNeedleConfig = NULL;   // config page lazy-loaded
    ui_ScreenPageMultiGauge = NULL;     // triple-gauge settings page lazy-loaded
    ui_ScreenPageAlertMedia = NULL;
    ui_ScreenPageChartConfig = NULL;    // chart data-source selection page lazy-loaded
    ui_ScreenPageChartAlarm = NULL;     // chart alarm settings page lazy-loaded
    ui_ScreenPageIntro = NULL;          // boot animation page lazy-loaded
    ui_ScreenPageThemeGauge = NULL;     // theme-provided gauge page, lazy-loaded (only reachable if the active theme declares "main_gauge")
    ui____initial_actions0 = lv_obj_create(NULL);

    // Pre-create lazy boot pages before the boot switch so they do not build
    // synchronously mid-transition. The other built-in gauge pages are eager.
    if (nvs_cfg_get()->default_page == 1 && ui_ScreenPageInfo == NULL) {
        ui_ScreenPageInfo_screen_init();
    } else if (nvs_cfg_get()->default_page == 7 && ui_ScreenPageTpms == NULL) {
        ui_ScreenPageTpms_screen_init();
    } else if (nvs_cfg_get()->default_page == 8 && ui_ScreenPageMultiGauge == NULL) {
        ui_ScreenPageMultiGauge_screen_init();
    }

    lv_timer_create(my_timerMain,
                    ui_refresh_period_ms_for_screen(lv_scr_act(), false, false, false),
                    NULL);
}

/* OBD protocol page events */
void ui_event_obd_prot_background(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if(code == LV_EVENT_LONG_PRESSED){
        usSaveProtTimeCnt = 0;
    }else if(code == LV_EVENT_LONG_PRESSED_REPEAT){
        usSaveProtTimeCnt += 100; // this event fires every 100 ms
        if(usSaveProtTimeCnt >= SAVE_PROTOCOL_TIME){
            usSaveProtTimeCnt = 0;
            nvs_user_cfg_t cfg = *nvs_cfg_get();
            cfg.protocol = lv_roller_get_selected(ui_RollerODBProtocalChoose);
            nvs_cfg_set(&cfg);
            esp_restart();
        }
    }else if(code == LV_EVENT_RELEASED){
        usSaveProtTimeCnt = 0;
    }
}

static void ui_nav_ble_leave(void)
{
    ui_ble_scan_page_leave();
}
